'use strict';
const app=document.querySelector('#app');
const holidays=[{id:'hangeul',name:'한글날',date:'10.09',tag:'말과 글이 만나는 날',body:'마음을 전하는 우리 글자,<br>한글의 이야기를 만나 볼까요?',featured:true},{id:'gaecheon',name:'개천절',date:'10.03',tag:'우리의 시작을 만나는 날',body:'아주 오래전 이야기 속으로,<br>우리나라의 시작을 찾아서.',featured:true},{id:'samil',name:'3·1절',date:'03.01',body:'독립을 향한<br>한마음의 외침'},{id:'constitution',name:'제헌절',date:'07.17',body:'함께 지키는 약속,<br>대한민국 헌법'},{id:'liberation',name:'광복절',date:'08.15',body:'다시 찾은 빛,<br>되찾은 우리나라'}];
const assetNames={hangeul:'hangul',gaecheon:'gaecheon',samil:'samil',constitution:'constitution',liberation:'liberation'};
function header(){return `<header class="topbar"><button class="brand" data-action="home" aria-label="오늘의 국경일 첫 화면"><span class="brand-mark">ㅎ</span>오늘의 국경일</button><nav class="topnav" aria-label="주 메뉴"><button class="active" data-action="home">국경일 수업</button><button class="nav-guide" data-action="guide">수업 안내</button><span class="tag teacher-tag">초등 3–4학년 · 교사용</span></nav></header>`}
function home(){app.innerHTML=header()+`<main class="page"><div class="intro"><div><div class="eyebrow">OUR DAYS, OUR STORIES</div><h1>특별한 날, 함께 배우는<br>우리의 이야기.</h1><p>보고, 만들고, 생각하며 만나는 우리나라 국경일</p></div><div class="season-note"><span>✳</span> 10월, 두 가지 이야기를 열어요</div></div><div class="bento">${holidays.map(h=>`<button class="holiday-card ${h.id} ${h.featured?'featured':''}" data-holiday="${h.id}"><div class="card-copy"><span class="date date-dot">${h.date}</span>${h.featured?`<span class="label">${h.tag}</span>`:''}<h2>${h.name}</h2><p>${h.body}</p></div><div class="card-footer"><span>${h.featured?'40분 수업 · 활동 + 골든벨':'어떤 날일까요?'}</span><span class="card-arrow" aria-hidden="true">↗</span></div></button>`).join('')}</div><div class="class-strip"><span class="strip-icon">✦</span><div><h3>함께 참여하면 더 즐거운 수업</h3><p>화면을 넘기며 배우고, 나만의 생각으로 완성해요.</p></div><div class="steps">이야기 <span>→</span> 영상 <span>→</span> 참여 활동 <span>→</span> 골든벨</div></div><footer class="footer"><span>오늘의 국경일 · 작은 배움이 모여 깊어지는 우리 이야기</span><button data-action="sources">자료 출처 ↗</button></footer></main>`;}
app.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-holiday]');if(!target)return;if(target.dataset.action==='home')home();else toast('수업 자료를 준비하고 있어요. 곧 이 화면에서 시작할 수 있습니다.');});
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
home();
